using System;
using System.Reflection;
using UnityEditor;
using UnityEditor.XR.Management;
using UnityEditor.XR.Management.Metadata;
using UnityEngine;
using UnityEngine.XR.Management;

namespace DiyVr.EditorTools
{
    /// <summary>
    /// Enables the ARCore XR loader for Android and sets ARCore to Required with Depth optional.
    /// XR settings assets carry package-internal GUIDs, so they are generated by the editor on first
    /// load instead of being written by hand. Idempotent. CI can also call
    /// DiyVr.EditorTools.ProjectSetup.Configure via -executeMethod.
    /// </summary>
    public static class ProjectSetup
    {
        private const string ArCoreLoader = "UnityEngine.XR.ARCore.ARCoreLoader";

        [InitializeOnLoadMethod]
        private static void OnLoad()
        {
            EditorApplication.delayCall += () =>
            {
                try { Configure(); }
                catch (Exception e) { Debug.LogWarning("DIY VR project setup failed: " + e); }
            };
        }

        public static void Configure()
        {
            EnableArCoreLoader();
            ConfigureArCoreSettings();
            AssetDatabase.SaveAssets();
        }

        private static void EnableArCoreLoader()
        {
            var group = BuildTargetGroup.Android;
            if (!EditorBuildSettings.TryGetConfigObject(XRGeneralSettings.k_SettingsKey,
                    out XRGeneralSettingsPerBuildTarget perBuild))
            {
                perBuild = ScriptableObject.CreateInstance<XRGeneralSettingsPerBuildTarget>();
                if (!AssetDatabase.IsValidFolder("Assets/XR")) AssetDatabase.CreateFolder("Assets", "XR");
                AssetDatabase.CreateAsset(perBuild, "Assets/XR/XRGeneralSettingsPerBuildTarget.asset");
                EditorBuildSettings.AddConfigObject(XRGeneralSettings.k_SettingsKey, perBuild, true);
            }

            if (!perBuild.HasManagerSettingsForBuildTarget(group))
                perBuild.CreateDefaultManagerSettingsForBuildTarget(group);

            var manager = perBuild.ManagerSettingsForBuildTarget(group);
            if (!XRPackageMetadataStore.AssignLoader(manager, ArCoreLoader, group))
                throw new InvalidOperationException("Could not assign " + ArCoreLoader);
            EditorUtility.SetDirty(perBuild);
        }

        private static void ConfigureArCoreSettings()
        {
            // ARCoreSettings lives in a package editor assembly; find the asset by type name instead of
            // reflecting a type path. Assigning the loader already creates it under Assets/XR/Settings.
            UnityEngine.Object settings = null;
            foreach (var guid in AssetDatabase.FindAssets("t:ARCoreSettings"))
            {
                settings = AssetDatabase.LoadMainAssetAtPath(AssetDatabase.GUIDToAssetPath(guid));
                if (settings != null) break;
            }
            if (settings == null)
                throw new InvalidOperationException("No ARCoreSettings asset found");

            var so = new SerializedObject(settings);
            var names = new System.Text.StringBuilder();
            var it = so.GetIterator();
            for (bool next = it.NextVisible(true); next; next = it.NextVisible(false))
                names.Append(it.propertyPath).Append(',');
            Debug.Log("ARCoreSettings fields: " + names);

            SetEnum(so, "m_Requirement", 0); // Required
            SetEnum(so, "m_Depth", 1);       // Optional
            so.ApplyModifiedPropertiesWithoutUndo();
            EditorUtility.SetDirty(settings);
        }

        private static void SetEnum(SerializedObject so, string name, int value)
        {
            var p = so.FindProperty(name);
            if (p == null) throw new InvalidOperationException("ARCoreSettings has no field " + name);
            p.enumValueIndex = value;
        }
    }
}
